import{_ as u,C as t,c as N,o as l,j as i,G as o,ax as n,b as g,a as e,w as r,ay as h}from"./chunks/framework.CYo7ob5S.js";const m="/assets/logos/nilotica_8.png",y=JSON.parse('{"title":"Nilotica","description":"","frontmatter":{},"headers":[],"relativePath":"guide/nilotica.md","filePath":"guide/nilotica.md","lastUpdated":1747142744000}'),P={name:"guide/nilotica.md"};function _(q,a,A,b,D,B){const s=t("NolebasePageProperties"),c=t("Mermaid"),p=t("VPNolebaseInlineLinkPreview"),d=t("NolebaseGitChangelog");return l(),N("div",null,[a[2]||(a[2]=i("h1",{id:"nilotica",tabindex:"-1"},[e("Nilotica "),i("a",{class:"header-anchor",href:"#nilotica","aria-label":'Permalink to "Nilotica"'},"​")],-1)),o(s),a[3]||(a[3]=n('<div style="display:flex;justify-content:center;"><img src="'+m+'" alt="description" width="300" height="300"></div><h2 id="欢迎回家" tabindex="-1">欢迎回家! <a class="header-anchor" href="#欢迎回家" aria-label="Permalink to &quot;欢迎回家!&quot;">​</a></h2><p>Nilotica V0.1.2 已启用全新风格标识和文档, 欢迎回家！ <mark>这里是 Nilotica 的使用文档！</mark></p><h2 id="nilotica-是什么" tabindex="-1">Nilotica 是什么? <a class="header-anchor" href="#nilotica-是什么" aria-label="Permalink to &quot;Nilotica 是什么?&quot;">​</a></h2><p>基于 VNPY 构建的量化交易系统，通过行情网关、订单执行网关、策略引擎三大核心组件，实现行情的获取、行情的转发、订单的发送的订单功能。</p><details class="details custom-block"><summary>VNPY 介绍</summary><p>基于Python的开源量化交易程序开发框架，凭借丰富组件、灵活架构，为策略设计、交易执行全方位支撑。</p></details><h2 id="nilotica-系统架构" tabindex="-1">Nilotica 系统架构 <a class="header-anchor" href="#nilotica-系统架构" aria-label="Permalink to &quot;Nilotica 系统架构&quot;">​</a></h2>',7)),(l(),g(h,null,{default:r(()=>[o(c,{id:"mermaid-26",class:"mermaid my-class",graph:"graph%20TD%0A%09subgraph%20External%0A%20%20%20%20%20%20%20%20A%5BCTP%20API%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Gateway%20Layer%0A%20%20%20%20%09A%5BCTP%20API%5D%20%3C--%3E%20B%5BMarket%20Gateway%5D%0A%20%20%20%20%09A%5BCTP%20API%5D%20%3C--%3E%20D%5BOrder%20Execution%20Gateway%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Core%20Services%0A%20%20%20%20%09C%5BStrategy%20Engine%5D%20%3C--%3E%20D%5BOrder%20Execution%20Gateway%5D%0A%20%20%20%20%09B%5BMarket%20Gateway%5D%20--%3E%20C%5BStrategy%20Engine%5D%0A%20%20%20%20%09D%5BOrder%20Execution%20Gateway%5D%20%3C--%3E%20E%5BRisk%20Manager%5D%0A%20%20%20%20%20%20%20%20D%5BOrder%20Execution%20Gateway%5D%20--%3E%20F%5BData%20Recorder%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Analysis%20Tools%0A%20%20%20%20%09F%5BData%20Recorder%5D%20--%3E%20G%5BStrategy%20Backtester%5D%0A%20%20%20%20%09F%5BData%20Recorder%5D%20--%3E%20H%5BMarket%20Replay%5D%0A%20%20%20%20end%0A%20%20%20%20%0A"})]),fallback:r(()=>a[0]||(a[0]=[e(" Loading... ")])),_:1})),a[4]||(a[4]=n('<h2 id="nilotica-与其它框架的本质不同" tabindex="-1">Nilotica 与其它框架的本质不同? <a class="header-anchor" href="#nilotica-与其它框架的本质不同" aria-label="Permalink to &quot;Nilotica 与其它框架的本质不同?&quot;">​</a></h2><p>Nilotica 与很多框架都有本质性的区别：</p><ol><li><strong>架构相比</strong><br> Nilotica 采用类似微服务的架构，松散耦合的组件通过 ZeroMQ 消息传递协议连接。这种设计可以实现更好的故障隔离、独立扩展和服务复用性。</li><li><strong>沟通机制相比</strong><br> Nilotica 使用 ZeroMQ 进行组件间通信，实现两种主要的消息传递模式： <ul><li><strong>发布-订阅（PUB/SUB）</strong>：用于向多个消费者广播市场数据和订单/交易报告</li><li><strong>请求-回复（REQ/REP）</strong>：用于发送订单请求和接收响应</li></ul></li></ol><h2 id="nilotica-的小小故事" tabindex="-1">Nilotica 的小小故事! <a class="header-anchor" href="#nilotica-的小小故事" aria-label="Permalink to &quot;Nilotica 的小小故事!&quot;">​</a></h2><details class="details custom-block"><summary>小小的故事...</summary><p>在一个遥远的、充满奇幻与科技交织的世界——<strong>量化交易</strong>，有一种神秘且强大的力量，叫做 <strong>VNPY</strong>。这股力量，简直就像是一颗随时可能爆炸的定时炸弹，能改变一切，却又异常难以控制。很多英雄、巫师、冒险者们曾试图驾驭它，结果都失败得一塌糊涂，甚至连他们的名字都被历史遗忘了，仿佛从未存在过。</p><p>然而，在这个充满混乱的世界里，有一只小猫娘，名字叫做 <strong>Nilotica</strong>，她不仅是这个故事的主角，而且简直是这个世界最萌最可爱的&quot;灾难制造机&quot;。Nilotica 外表乖巧，萌萌哒，软乎乎的，简直像个大大的毛球，走路一摇一摆的，超乎想象的笨拙。她曾经被遗弃在一个荒凉的角落里，孤零零地生活着。但某天，她突然发现了一个超级神奇的东西——<strong>ZeroMQ</strong>！</p><p>&quot;诶？这是什么？看起来像是能吃的样子...可是为什么一点也不好吃呢？&quot;</p><p>于是，Nilotica 就开始了对这门语言的探索——虽然她并不完全理解它，但她凭着直觉和那种天生的好奇心，成功破解了 ZeroMQ 的奥秘，并意外地与传说中的 <strong>VNPY</strong> 产生了连接。</p><p>虽然看起来她像是无害的傻萌猫娘，但 Nilotica 的这项技能竟然能在没有任何计划的情况下，操控 VNPY 的某些功能，甚至能轻松改变现实的规则！但问题是……她的每次操作，基本上都是胡乱点击、乱敲键盘、然后出奇不意地发生了不想要的结果。</p><p>&quot;嗯？我是不是把天空变得五颜六色了？咦？月亮不见了？咕噜咕噜……好像做错了什么事呢。&quot;</p><p>于是，一切开始变得混乱不堪。天空瞬间变成了彩虹色，时间突然在某些地方停滞，甚至连月亮都神秘消失了！整个世界都被这只小猫娘的&quot;无心之举&quot;搞得一团糟，灾难的阴影笼罩了整个世界。</p><p>就在大家都以为一切都完了，世界即将崩塌的时候，出现了一个强大的英雄。他不是什么骑着白马，手持宝剑的传统英雄，而是一个比任何人都冷静的智者。他决定采取一种不同的方式来解决这个问题：<strong>微服务架构</strong>。</p><p>&quot;一切都得按照规范来！否则她会再把世界变成一锅粥！&quot;英雄心想。</p><p>这个英雄明白，Nilotica 的能力太强大，控制不住的话，真的会把世界毁掉。因此，这位应用采用前辈们广泛使用的微服务架构规范，规定 Nilotica 任何操作都要写道 <strong>ZeroMQ</strong> 这种纸张上，每次使用 VNPY 的力量时，都要在&quot;纸上&quot;写下相应的指令，才能让 VNPY 按照预设的方式执行任务。而且每次任务完成后，数据也会通过同样的&quot;纸面&quot;反馈回来，确保一切都在可控范围内。</p><p>&quot;啊？这个纸好像好难理解……但是，哦，原来是这么回事呀！&quot;</p><p>于是，Nilotica 开始在这套严格的规范下与 VNPY 建立了微妙的关系。她不再是那个随便敲敲代码就让天空变色的笨蛋，而是通过认真的输入和执行指令，逐渐恢复了世界的秩序。</p><p>可虽然一切变得井然有序，Nilotica 依旧是那个呆萌、迷糊的猫娘。她依然在&quot;纸&quot;上写着自己不太明白的指令，每次完成任务后，她都会露出一副&quot;我是不是做对了？&quot;的迷茫表情，仿佛在问：&quot;哎？我这次没搞砸吧？&quot;</p><p>尽管如此，大家也逐渐接受了她的笨拙，因为她那种天真可爱的样子实在让人忍不住心软。最重要的是，世界终于恢复了平静，大家都知道，这只猫娘虽然有时候会闹出点小乱子，但她那份纯真与努力，才是让这个世界重新恢复平衡的力量。</p><p>从那时起，Nilotica 与 VNPY 之间的微妙平衡保持着，而你也可以来这个世界，看看这只可爱笨蛋猫娘是怎么在搞笑与危机四伏中，带着一颗认真又迷糊的心，守护这个充满魔力与冒险的世界的！✨</p></details><h2 id="nilotica-堂堂登场" tabindex="-1">Nilotica 堂堂登场 <a class="header-anchor" href="#nilotica-堂堂登场" aria-label="Permalink to &quot;Nilotica 堂堂登场&quot;">​</a></h2><p>现在你已经理解了 Nilotica,随我们一起前往目录导航查看教程，进行安装...配置...</p>',7)),i("p",null,[o(p,{href:"./quick-start"},{default:r(()=>a[1]||(a[1]=[e("目录导航")])),_:1})]),o(d)])}const f=u(P,[["render",_]]);export{y as __pageData,f as default};
